head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > dataType]<br/>InputBox 컴포넌트의 입력값 형식을 설정합니다.",
    "validation" : [
        "미설정 시 'text' 값으로 동작합니다.",
        "'text', 'number', 'float', 'date', 'time', 'bigDecimal', 'euro', 'rupee', 'tenge' 값 중 하나를 문자열로 설정할 수 있습니다.",
        "'text' 설정 시, 문자 형식으로 displayFormat 속성 등에서 참조합니다.",
        "'number' 설정 시, 숫자 형식으로 adjustMaxLength, numberMask 속성 등에서 참조합니다.",
        "'float' 설정 시, 소수 형식으로 autoDecimalPoint, maxlength 속성 등에서 참조합니다.",
        "'date' 설정 시, 날짜 형식으로 ioFormat, useMonthYearFormat 속성 등에서 참조합니다.",
        "'time' 설정 시, 시간 형식으로 ioFormat 속성 등에서 참조합니다.",
        "'bigDecimal' 설정 시, 고정밀 소수 형식으로 displayFormat 속성 등에서 참조합니다.",
        "'euro' 설정 시, 유로 통화 형식으로 euroMask 속성 등에서 참조합니다.",
        "'rupee' 설정 시, 인도 루피 통화 형식으로 rupeeMask 속성 등에서 참조합니다.",
        "'tenge' 설정 시, 카자흐스트탄 텡게 통화 형식으로 tengeMask 속성 등에서 참조합니다.",
        "\"date\" 설정 시 8자리 숫자로 입력하여야 정상적인 날짜 표현이 가능합니다.",
        "\"time\" 설정 시 6자리를 초과한 입력값은 잘리고, 6자리 미만인 경우 0 값이 추가됩니다.",
        "\"text\", \"date\", \"time\" 값 이외의 값을 설정했을때 allowChar 속성을 설정하지 않았다면 숫자, \"+\", \"-\", \".\" 만 입력할 수 있습니다.",
        "setValue() 로 입력값을 설정하면 dataType 속성에 관계없이 모든 문자가 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성/재생성
scwin.comp_init = function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let dt = con_dataType.getValue();

    let properties = {};
    // createEmptyInput 은 style 을 넣지 않아 기본 너비가 과도하게 커짐 -> 크기 지정
    properties.style = 'width:200px; height:30px;';

    // dataType 에 필요한 마스크만 생성 시 함께 설정한다. (마스크는 생성 속성 @dynamic N)
    // 초기값은 빈값(테스트 시 직접 입력) -> initValue="input" 이 없는 createEmptyInput 사용.
    if (dt !== '') {
        properties.dataType = dt;
        if (dt === 'number' || dt === 'float' || dt === 'bigDecimal') {
            properties.numberMask = '#,###.#0[round]';
        } else if (dt === 'euro') {
            properties.euroMask = '€#.###,#0[round]';
        } else if (dt === 'rupee') {
            properties.rupeeMask = '₹#,###.#0[round]';
        } else if (dt === 'tenge') {
            properties.tengeMask = '# ###,#0[floor]₸';
        } else if (dt === 'time') {
            // time 은 displayFormat 미설정 시 기본 "HH:mm"(초 미표시) -> 초까지 표시
            properties.displayFormat = 'HH:mm:ss';
        }
    }

    let cList = $c.gcm.createCList(properties);
    // 값 입력 후 포커스 아웃(onblur) 시 리턴 창에 값 출력
    let eList = $c.gcm.createEList(['onblur'], 'target1');

    // 빈값으로 생성 (createEmptyInput: initValue 없음)
    $c.gcm.createEmptyInput(cList, eList);
};



scwin.btn_getDataType_onclick = function (e) {
    let rtn = target1.getDataType();
    wf_body_bottom.getObj("scwin").setReturnValue("getDataType : " + rtn);
};



scwin.btn_setValue_onclick = function (e) {
    let v = par_setValue.getValue();
    target1.setValue(v);
    wf_body_bottom.getObj("scwin").setReturnValue("setValue('" + v + "') -> getValue() : '" + target1.getValue() + "' (dataType: " + target1.getDataType() + ")");
};



// 값 입력 후 포커스 아웃 시 표시값(마스크 포맷 적용된 값)을 리턴 창에 출력
scwin.target1_onblur = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("표시값 : " + target1.getFormattedValue());
};
